const $=s=>document.querySelector(s);
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={index:null,trip:null,selected:null,snapshot:0,stop:0,metric:'departure',measured:true,playing:null,request:0};
const zone='America/Winnipeg';
const clock=new Intl.DateTimeFormat('en-CA',{timeZone:zone,hour:'2-digit',minute:'2-digit',hour12:false});
const clockSeconds=new Intl.DateTimeFormat('en-CA',{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const dateFormat=new Intl.DateTimeFormat('en-CA',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'});
const time=(value,seconds=false)=>value==null?'—':(seconds?clockSeconds:clock).format(new Date(value*1000));
const dateText=value=>dateFormat.format(new Date(value+'T12:00:00Z'));
const signed=value=>value==null?'—':Math.abs(value)<1?'0:00':`${value<0?'−':'+'}${Math.floor(Math.abs(value)/60)}:${String(Math.round(Math.abs(value))%60).padStart(2,'0')}`;
const delayBadge=value=>value==null?'<span class="dash">—</span>':`<span class="delay ${Math.abs(value)<=120?'near':value>0?'late':'early'}">${signed(value)}</span>`;
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').classList.remove('show'),4200)}
async function json(url){const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw new Error(`Data could not be loaded (${response.status}).`);return response.json()}
function filtered(){const text=$('#search').value.toLowerCase().replace(/\b(bus|trip)\s*/g,'').trim();return state.index.trips.filter(t=>t.date===$('#date').value&&(!$('#destination').value||t.destination===$('#destination').value)&&(!text||t.bus.toLowerCase().includes(text)||t.trip.toLowerCase().includes(text)))}
function updateFilters(){const values=[...new Set(state.index.trips.filter(t=>t.date===$('#date').value).map(t=>t.destination).filter(Boolean))].sort();const old=$('#destination').value;$('#destination').innerHTML='<option value="">All destinations</option>'+values.map(v=>`<option value="${h(v)}">${h(v)}</option>`).join('');if(values.includes(old))$('#destination').value=old}
function renderList(){const rows=filtered();$('#trip-count').textContent=`${rows.length} trip${rows.length===1?'':'s'}`;$('#trip-list').innerHTML=rows.length?rows.map(t=>`<button class="trip-card" data-trip="${h(t.id)}" aria-pressed="${t.id===state.selected}"><span class="top"><span>Bus ${h(t.bus||'unknown')}</span><time>${time(t.start)}</time></span><span class="dest">${h(t.destination||t.variant)}</span><span class="sub"><span>Trip ${h(t.trip)}</span><span class="${t.measuredStops?'coverage':''}">${t.measuredStops?`${t.measuredStops} measured stops`:'Estimates only'}</span></span></button>`).join(''):'<div class="no-trip">No trips match these filters. Try another bus, date, or destination.</div>';$('#trip-list').querySelectorAll('[data-trip]').forEach(button=>button.addEventListener('click',()=>selectTrip(button.dataset.trip)));return rows}
async function filterChanged(){stopPlayback();const rows=renderList();if(!rows.some(t=>t.id===state.selected)){if(rows.length)await selectTrip(rows[0].id);else{state.selected=null;state.trip=null;state.request++;$('#detail').innerHTML='<div class="panel empty-state"><strong>No matching trips</strong>Adjust the filters to explore another bus.</div>'}}}
async function selectTrip(id){stopPlayback();const summary=state.index.trips.find(t=>t.id===id);if(!summary)throw new Error('Trip is not in this dataset.');state.selected=id;renderList();const request=++state.request;$('#detail').innerHTML='<div class="panel empty-state">Loading trip history…</div>';try{const trip=await json(`data/trips/${encodeURIComponent(id)}.json`);if(request!==state.request)return;state.trip=trip;state.snapshot=trip.snapshots.length-1;state.stop=0;renderDetail();const url=new URL(location.href);url.searchParams.set('trip',id);history.replaceState(null,'',url);return {trip:id,bus:trip.bus,stops:trip.stops.length,snapshots:trip.snapshots.length}}catch(error){if(request!==state.request)return;state.trip=null;$('#detail').innerHTML=`<div class="panel empty-state"><strong>Trip couldn’t be loaded</strong>${h(error.message)}<br><button class="button" id="retry-trip">Try again</button></div>`;$('#retry-trip').onclick=()=>selectTrip(id);notify('Couldn’t load this trip. Try reloading the data.');throw error}}
function values(){const trip=state.trip,snapshot=trip.snapshots[state.snapshot],arrival=state.metric==='arrival';return trip.stops.map((stop,i)=>{const scheduled=arrival?stop.scheduledArrival:stop.scheduled,estimated=snapshot.times[i][arrival?1:0],cancelled=snapshot.times[i][2];return {stop,scheduled,estimated,cancelled,delay:scheduled!=null&&estimated!=null&&!cancelled?estimated-scheduled:null,actual:!arrival?stop.actual:null,actualDelay:!arrival&&stop.actual!=null?stop.actual-stop.scheduled:null}})}
function renderDetail(){const t=state.trip;if(!t)return;const count=t.stops.filter(s=>s.actual!=null).length;const summary=state.index.trips.find(s=>s.id===t.id);$('#detail').innerHTML=`<div class="trip-header"><div><div class="trip-kicker">${dateText(t.date)} · Trip ${h(t.trip)} · ${h(t.variant)}</div><h2>${h(t.destination||'BLUE trip')}<span class="bus-pill">Bus ${h(t.bus||'unknown')}</span></h2><p class="trip-subtitle"><strong>${time(t.stops[0].scheduled)}–${time(t.stops.at(-1).scheduled)}</strong> scheduled · ${t.stops.length} stops · ${t.snapshots.length} captures</p></div><div class="metric-control"><label for="metric">Show times for</label><select id="metric"><option value="departure">Departure</option><option value="arrival">Arrival estimates</option></select></div></div>
<div id="pending" class="pending" ${count?'hidden':''}>Measured departure records are unavailable for this trip. You can still replay its captured estimates.</div>
<div class="stats" id="stats"></div>
<section class="panel" aria-label="Delay along the trip"><div class="panel-head"><div><h3>Delay along the trip</h3><p>Above zero = late · below zero = early · shaded band = within ±2 minutes</p></div><div class="legend"><span><i class="swatch"></i>API estimate</span><label><input id="measured" type="checkbox" ${state.measured?'checked':''}><span><i class="swatch actual"></i>Measured departure</span></label></div></div><div class="chart-wrap" id="chart"></div><div id="inspector" class="stop-inspector"></div><div class="replay"><button id="play" class="button" aria-label="Play captured snapshots">▶ Play</button><div><label for="snapshot"><span>Captured estimates</span><time id="snapshot-time"></time></label><input id="snapshot" type="range" min="0" max="${t.snapshots.length-1}" value="${state.snapshot}" aria-label="Captured snapshot"></div><span class="counter" id="snapshot-counter"></span></div><div id="timing-note" class="info-strip"></div></section>
<section class="panel"><div class="panel-head"><div><h3>Stop-by-stop performance</h3><p id="table-caption">Select a stop to inspect its times.</p></div><span class="count">${h(summary.from)} → ${h(summary.to)}</span></div><div class="table-scroll"><table><thead id="table-head"></thead><tbody id="stop-table"></tbody></table></div></section>`;
$('#metric').value=state.metric;$('#metric').onchange=()=>{state.metric=$('#metric').value;renderSnapshot()};$('#measured').onchange=()=>{state.measured=$('#measured').checked;renderSnapshot()};$('#snapshot').oninput=()=>{stopPlayback();state.snapshot=Number($('#snapshot').value);renderSnapshot()};$('#play').onclick=togglePlayback;renderSnapshot()}
function renderSnapshot(){if(!state.trip)return;const t=state.trip,data=values(),arrival=state.metric==='arrival';const measured=data.filter(v=>v.actualDelay!=null).map(v=>v.actualDelay);const estimated=data.filter(v=>v.delay!=null).map(v=>v.delay);const population=measured.length?measured:estimated;const sorted=[...population].sort((a,b)=>a-b);const median=sorted.length?(sorted[Math.floor((sorted.length-1)/2)]+sorted[Math.ceil((sorted.length-1)/2)])/2:null;const within=population.length?Math.round(population.filter(v=>Math.abs(v)<=120).length/population.length*100):null;const source=measured.length?'Measured departures':'API estimates · this capture';$('#stats').innerHTML=`<div class="stat"><span class="label">Median delay</span><strong class="value">${signed(median)}</strong><span class="hint">${source}</span></div><div class="stat"><span class="label">Within ±2 minutes</span><strong class="value">${within==null?'—':within+'%'}</strong><span class="hint">${population.length} stops · ${measured.length?'measured':'estimated'}</span></div><div class="stat"><span class="label">Measured coverage</span><strong class="value">${arrival?'—':measured.length+' / '+data.length}</strong><span class="hint">${arrival?'Actual arrivals unavailable':'Matched departure records'}</span></div>`;$('#measured').disabled=arrival||!measured.length;$('#snapshot').value=state.snapshot;$('#snapshot-time').textContent=time(t.snapshots[state.snapshot].at,true);$('#snapshot-counter').textContent=`${state.snapshot+1} of ${t.snapshots.length}`;$('#snapshot').setAttribute('aria-valuetext',`${time(t.snapshots[state.snapshot].at,true)}, snapshot ${state.snapshot+1} of ${t.snapshots.length}`);$('#play').disabled=t.snapshots.length<2;$('#timing-note').textContent=arrival?'Arrival times are API forecasts. No measured arrival outcomes are available.':'Replay changes the recorded API estimates. Measured departures are later outcomes and stay fixed; they were not necessarily known at capture time.';$('#table-head').innerHTML=`<tr><th>Stop</th><th>Scheduled</th><th>API estimate</th><th>Est. delay</th>${arrival?'':'<th>Measured</th><th>Actual delay</th>'}</tr>`;$('#stop-table').innerHTML=data.map((r,i)=>`<tr class="${i===state.stop?'selected':''}" data-row="${i}"><td class="stop-cell"><button data-stop="${i}" aria-label="Inspect stop ${i+1}: ${h(r.stop.name)}"><span class="stop-number">${i+1}</span><span>${h(r.stop.name)}<small>Stop ${h(r.stop.number)}${r.cancelled?' · Cancelled in this capture':''}</small></span></button></td><td>${time(r.scheduled,true)}</td><td>${r.cancelled?'Cancelled':time(r.estimated,true)}</td><td>${delayBadge(r.delay)}</td>${arrival?'':`<td title="${r.stop.matchStatus==='ambiguous'?'Ambiguous match excluded':r.actual==null?'No unique measured match':'City outcome '+h(r.stop.outcomeRowId)}">${time(r.actual,true)}</td><td>${delayBadge(r.actualDelay)}</td>`}</tr>`).join('');$('#stop-table').querySelectorAll('[data-stop]').forEach(button=>button.onclick=()=>selectStop(Number(button.dataset.stop)));renderChart(data);renderInspector(data)}
function renderChart(data){const W=Math.max(280,Math.min(1200,$('#chart').clientWidth||940)),H=295,p={l:57,r:24,t:30,b:43},plotW=W-p.l-p.r,plotH=H-p.t-p.b;const actual=state.metric==='departure'&&state.measured;const all=[-120,120,...data.flatMap(v=>[v.delay,...(actual?[v.actualDelay]:[])]).filter(v=>v!=null)].map(v=>v/60);let min=Math.floor(Math.min(...all))-1,max=Math.ceil(Math.max(...all))+1;if(max-min<6){max=3;min=-3}const x=i=>p.l+(data.length>1?i/(data.length-1):.5)*plotW,y=v=>p.t+(max-v)/(max-min)*plotH;const path=key=>{let d='',connected=false;data.forEach((v,i)=>{if(v[key]==null){connected=false;return}d+=`${connected?'L':'M'}${x(i).toFixed(1)},${y(v[key]/60).toFixed(1)} `;connected=true});return d};const step=Math.max(1,Math.ceil((max-min)/6));let grid='';for(let tick=Math.ceil(min/step)*step;tick<=max;tick+=step){grid+=`<line x1="${p.l}" x2="${W-p.r}" y1="${y(tick)}" y2="${y(tick)}" stroke="${tick===0?'#8296ae':'#e7edf5'}" ${tick===0?'stroke-dasharray="4 4"':''}/><text x="${p.l-12}" y="${y(tick)+4}" text-anchor="end">${tick>0?'+':''}${tick}m</text>`}let labels='';const labelCount=Math.min(6,data.length);for(let n=0;n<labelCount;n++){const i=Math.round(n/Math.max(1,labelCount-1)*(data.length-1));labels+=`<text x="${x(i)}" y="${H-20}" text-anchor="middle">${i+1}</text>`}const selected=data[state.stop];const dots=data.map((v,i)=>`${v.delay!=null?`<circle data-point="${i}" cx="${x(i)}" cy="${y((v.delay??0)/60)}" r="${i===state.stop?6:4}" fill="${v.delay==null?'#b8c7d7':'#1479da'}" stroke="white" stroke-width="2" tabindex="0" role="button" aria-label="Stop ${i+1}, ${h(v.stop.name)}, estimate ${h(signed(v.delay))}"><title>${h(v.stop.name)}: ${h(signed(v.delay))}</title></circle>`:''}${actual&&v.actualDelay!=null?`<circle data-point="${i}" cx="${x(i)}" cy="${y(v.actualDelay/60)}" r="4" fill="#b26a05" stroke="white" stroke-width="1.5"><title>Measured departure: ${h(signed(v.actualDelay))}</title></circle>`:''}`).join('');$('#chart').innerHTML=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${h(state.metric)} delay in minutes across ${data.length} stops. Select a stop in the table for exact values."><rect x="${p.l}" y="${y(2)}" width="${plotW}" height="${y(-2)-y(2)}" fill="#f0f7f6"/>${grid}<text class="axis-title" x="${p.l}" y="15">DELAY / MINUTES</text><text class="axis-title" x="${W-p.r}" y="${H-1}" text-anchor="end">STOP IN TRIP</text>${labels}<line x1="${x(state.stop)}" x2="${x(state.stop)}" y1="${p.t}" y2="${H-p.b}" stroke="#92acd0" stroke-dasharray="3 4"/>${actual?`<path d="${path('actualDelay')}" fill="none" stroke="#b26a05" stroke-width="2.5"/>`:''}<path d="${path('delay')}" fill="none" stroke="#1479da" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${dots}</svg>`;$('#chart').querySelectorAll('[data-point]').forEach(point=>{point.onclick=()=>selectStop(Number(point.dataset.point));point.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectStop(Number(point.dataset.point))}}})}
function renderInspector(data){const r=data[state.stop];$('#inspector').innerHTML=`<div><small>STOP ${state.stop+1} OF ${data.length} · #${h(r.stop.number)}</small><div class="stop-name">${h(r.stop.name)}</div></div><div><small>Scheduled ${state.metric}</small><span class="time">${time(r.scheduled,true)}</span></div><div><small>API ${state.metric}</small><span class="time">${r.cancelled?'Cancelled':time(r.estimated,true)}</span></div><div><small>${state.metric==='arrival'?'Measured arrival':'Measured departure'}</small><span class="time">${time(r.actual,true)}</span></div>`}
function selectStop(index){if(!state.trip||!Number.isInteger(index)||index<0||index>=state.trip.stops.length)throw new Error('Invalid stop index.');state.stop=index;$('#stop-table').querySelectorAll('tr').forEach(row=>row.classList.toggle('selected',Number(row.dataset.row)===index));const data=values();renderChart(data);renderInspector(data)}
function stopPlayback(){if(state.playing){clearInterval(state.playing);state.playing=null}if($('#play')){$('#play').textContent='▶ Play';$('#play').setAttribute('aria-label','Play captured snapshots')}}
function togglePlayback(){if(state.playing){stopPlayback();return}if(!state.trip||state.trip.snapshots.length<2)return;if(state.snapshot===state.trip.snapshots.length-1)state.snapshot=0;renderSnapshot();$('#play').textContent='Ⅱ Pause';$('#play').setAttribute('aria-label','Pause captured snapshots');state.playing=setInterval(()=>{if(state.snapshot>=state.trip.snapshots.length-1){stopPlayback();return}state.snapshot++;renderSnapshot()},1200)}
async function loadIndex(reload=false){const old=state.index;$('#refresh').disabled=true;try{const index=await json('data/index.json');if(!Array.isArray(index.trips))throw new Error('Invalid trip catalog.');state.index=index;const dates=[...new Set(index.trips.map(t=>t.date))].sort().reverse();const selected=index.trips.find(t=>t.id===(state.selected||new URL(location.href).searchParams.get('trip')||index.defaultTrip));const previousDate=$('#date').value;$('#date').innerHTML=dates.map(d=>`<option value="${d}">${dateText(d)}</option>`).join('');$('#date').value=dates.includes(previousDate)?previousDate:selected?.date||dates[0]||'';updateFilters();$('#data-range').textContent=`${index.trips.length} captured trips · ${new Set(index.trips.map(t=>t.bus)).size} buses`;const generated=new Date(index.generatedAt);$('#data-age').textContent=`Snapshot exported ${new Intl.DateTimeFormat('en-CA',{timeZone:zone,month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(generated)} · Winnipeg time`;renderList();if(!index.trips.length){$('#detail').innerHTML='<div class="panel empty-state"><strong>No captured trips yet</strong>Collect and export dated trip snapshots to begin.</div>';return}const rows=filtered();const next=rows.find(t=>t.id===selected?.id)||rows[0];if(next)await selectTrip(next.id);else await filterChanged();if(reload)notify(old?.generatedAt===index.generatedAt?'You’re viewing the latest exported snapshot.':'New snapshot loaded.')}catch(error){if(!state.index){$('#detail').innerHTML=`<div class="panel empty-state"><strong>Data is unavailable</strong>${h(error.message)}<br>Use Reload data to try again.</div>`;$('#trip-count').textContent='Data unavailable'}notify(error.message)}finally{$('#refresh').disabled=false}}
$('#date').onchange=()=>{updateFilters();filterChanged()};$('#search').oninput=filterChanged;$('#destination').onchange=filterChanged;$('#refresh').onclick=()=>loadIndex(true);$('#method-button').onclick=()=>{const hidden=$('#method').hidden;$('#method').hidden=!hidden;$('#method-button').setAttribute('aria-expanded',String(hidden));if(hidden)$('#method').scrollIntoView({behavior:'smooth',block:'nearest'})};
await loadIndex();
// Progressive agent access to the same visible controls; unsupported browsers remain fully usable.
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});const tools=[{name:'list_captured_trips',title:'List captured bus trips',description:'List the real trips in the dashboard, optionally filtered by local date or bus ID.',inputSchema:{type:'object',properties:{date:{type:'string'},bus:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['date','bus'].includes(k)))throw new Error('Provide optional date and bus strings.');if(input.date!==undefined&&typeof input.date!=='string'||input.bus!==undefined&&typeof input.bus!=='string')throw new Error('Date and bus must be strings.');return state.index.trips.filter(t=>(!input.date||t.date===input.date)&&(!input.bus||t.bus===input.bus)).map(({id,date,bus,trip,destination,start,captures,measuredStops})=>({id,date,bus,trip,destination,start,captures,measuredStops}))}},{name:'select_captured_trip',title:'Open a bus trip',description:'Select a captured trip and update the visible dashboard.',inputSchema:{type:'object',properties:{tripId:{type:'string'}},required:['tripId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length!==1||typeof input.tripId!=='string')throw new Error('Provide one tripId string.');const trip=state.index.trips.find(t=>t.id===input.tripId);if(!trip)throw new Error('Unknown trip ID.');$('#date').value=trip.date;$('#search').value='';updateFilters();$('#destination').value='';return await selectTrip(trip.id)}}];for(const tool of tools){try{await document.modelContext.registerTool(tool,{signal:controller.signal})}catch{ /* Optional capability; normal controls remain available. */ }}}
